from collections import Counter

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Isolated color deviations inside a long uniform stripe are the marked error.
    for r, row in enumerate(grid):
        fg = [v for v in row if v != bg]
        if not fg:
            continue
        main = Counter(fg).most_common(1)[0][0]
        if len(fg) >= max(4, w // 3):
            for c, v in enumerate(row):
                if v != bg and v != main:
                    out[r][c] = 1

    # Split the drawing into contiguous non-background row groups. Repeated groups
    # use the first group as their template; newly present foreground cells are marked.
    active = [any(v != bg for v in row) for row in grid]
    groups = []
    r = 0
    while r < h:
        if not active[r]:
            r += 1
            continue
        start = r
        while r < h and active[r]:
            r += 1
        groups.append((start, r))
    if len(groups) > 1:
        a0, a1 = groups[0]
        template = grid[a0:a1]
        for b0, b1 in groups[1:]:
            block = grid[b0:b1]
            if len(block) == len(template):
                if len(block) > 1:
                    for dr, (tr, br) in enumerate(zip(template, block)):
                        for c, (tv, bv) in enumerate(zip(tr, br)):
                            if bv != bg and bv != tv:
                                out[b0 + dr][c] = 1
                # For one-row stripe copies, mark the foreground part of a length difference.
                if len(block) == 1:
                    tr, br = template[0], block[0]
                    for c, (tv, bv) in enumerate(zip(tr, br)):
                        if tv != bg and bv == bg:
                            out[a0][c] = 1
                        elif bv != bg and tv == bg:
                            out[b0][c] = 1
    return out

